        MaterialIconKind.HandCoin => Payment,
        MaterialIconKind.AccountPlus => PersonAdd,
        MaterialIconKind.ChartBar => Chart,
        MaterialIconKind.FileChart => Document,
        MaterialIconKind.ReceiptText => Receipt,
        MaterialIconKind.ClipboardCheck => Clipboard,
        MaterialIconKind.ViewDashboard => Dashboard,
        MaterialIconKind.AccountGroup => People,
        MaterialIconKind.School => School,
        MaterialIconKind.CalendarMonth => Calendar,
        _ => Apps,
    };
    public static readonly IValueConverter Converter = new FuncValueConverter<MaterialIconKind, Geometry>(For);
}
